<script setup lang="ts">
import {t,locale} from '../i18n'

import {networkOnline} from '../offline'
import { computed,reactive,ref,watch,onBeforeUnmount } from 'vue'
import { X,Heart,MapPin,CalendarDays,Pencil,Plus,Trash2,Check,ArrowUp,ArrowDown,Image,Download,ChevronLeft,ChevronRight } from 'lucide-vue-next'
import { useModal } from '../useModal'
import { useAlbum } from '../store'
import { api,media,originalMedia,modes,type Memory,type Photo } from '../api'
import UploadDialog from './UploadDialog.vue'
import MemoryMap from './MemoryMap.vue'
import PhotoEditor from './PhotoEditor.vue'
import PlaceSearch,{type PlaceResult} from './PlaceSearch.vue'
const props=defineProps<{memory:Memory}>(),emit=defineEmits<{close:[];changed:[]}>()
const album=useAlbum(),dialog=useModal(),editing=ref(false),busy=ref(false),error=ref(''),confirmDelete=ref(false),adding=ref(false),editingPhoto=ref<Photo|null>(null),slide=ref(0),view=ref<'stream'|'slides'>('stream')
watch(()=>album.memories,items=>{if(!items.some(m=>m.id===props.memory.id))emit('close')})
const full=ref<Memory|null>(null),detailReady=ref(false),detailError=ref('')
let loadVersion=0,controller:AbortController|undefined
async function loadDetail(){const version=++loadVersion;controller?.abort();controller=new AbortController();try{const result=await api<Memory>(`/memories/${encodeURIComponent(props.memory.id)}`,{signal:controller.signal});if(version!==loadVersion)return;full.value=result;detailReady.value=true;detailError.value='';slide.value=Math.max(0,Math.min(slide.value,result.photos.length-1))}catch(e){if(version===loadVersion&&(e as Error).name!=='AbortError')detailError.value=(e as Error).message}}
watch(()=>[props.memory.id,album.revision],loadDetail,{immediate:true})
onBeforeUnmount(()=>{loadVersion++;controller?.abort()})
const memory=computed(()=>full.value||props.memory)
const form=reactive({...props.memory,tags:[...props.memory.tags],photo_ids:props.memory.photos.map(p=>p.id)})
const tagText=ref(form.tags.join('，'))
const ordered=computed(()=>form.photo_ids.map(id=>memory.value.photos.find(p=>p.id===id)).filter((p):p is Photo=>!!p))
function location(place:PlaceResult){form.place=place.name.slice(0,200);form.province=place.province;form.city=place.city;form.latitude=place.latitude;form.longitude=place.longitude}
function startEditing(){Object.assign(form,{...memory.value,tags:[...memory.value.tags],photo_ids:memory.value.photos.map(p=>p.id)});tagText.value=memory.value.tags.join('，');editing.value=true}
function move(index:number,direction:number){const target=index+direction;if(target<0||target>=form.photo_ids.length)return;[form.photo_ids[index],form.photo_ids[target]]=[form.photo_ids[target]!,form.photo_ids[index]!]}
function coordinate(event:Event,key:'latitude'|'longitude'){const value=(event.target as HTMLInputElement).value;form[key]=value===''?null:Number(value)}
async function save(){busy.value=true;error.value='';try{await api(`/memories/${memory.value.id}`,{method:'PUT',body:JSON.stringify({...form,photos:undefined,tags:tagText.value.split(/[,，]/).map(t=>t.trim()).filter(Boolean)})});await album.refresh();await loadDetail();editing.value=false;emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(){busy.value=true;error.value='';try{await api(`/memories/${memory.value.id}`,{method:'DELETE'});await album.refresh();emit('changed');emit('close')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function added(){await album.refresh();await loadDetail();form.photo_ids=memory.value.photos.map(p=>p.id);form.updated_at=memory.value.updated_at;emit('changed')}
function key(event:KeyboardEvent){if(event.key==='Escape'&&!adding.value&&!editingPhoto.value&&!busy.value)emit('close');if(view.value==='slides'&&!editing.value&&!adding.value&&!editingPhoto.value){if(event.key==='ArrowRight')slide.value=Math.min(memory.value.photos.length-1,slide.value+1);if(event.key==='ArrowLeft')slide.value=Math.max(0,slide.value-1)}}
</script>
<template><div class="overlay" @click.self="!busy&&emit('close')"><section ref="dialog" class="modal memory-detail" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="memory-title" @keydown="key"><button class="icon close" :disabled="busy" :aria-label="t('关闭回忆')" @click="emit('close')"><X/></button>
 <div class="memory-photo-panel"><div class="memory-photo-tools"><span>{{t('{0} 个瞬间', [memory.photos.length])}}</span><div class="view-switch"><button :class="{active:view==='stream'}" @click="view='stream'">{{t('照片流')}}</button><button :class="{active:view==='slides'}" @click="view='slides'">{{t('逐张看')}}</button></div></div>
  <div v-if="view==='stream'" class="memory-photo-stream"><figure v-for="(photo,index) in memory.photos" :key="photo.id"><img :src="media(photo.id)" :alt="photo.title||memory.title" loading="lazy"><figcaption><span>{{index+1}} / {{memory.photos.length}}</span><button class="text-button" :disabled="!detailReady" @click="editingPhoto=photo">{{t('编辑此照片')}}</button><a :href="networkOnline?originalMedia(photo.id):undefined" :aria-disabled="!networkOnline" @click="!networkOnline&&$event.preventDefault()" :title="networkOnline?t('下载原图'):t('原图下载需要联网')" :download="photo.filename" class="text-button" :aria-label="t('下载这张照片')"><Download :size="14"/></a></figcaption></figure></div>
  <div v-else class="memory-slides"><img v-if="memory.photos[slide]" :src="media(memory.photos[slide]!.id)" :alt="memory.photos[slide]!.title"><div class="slide-controls"><button class="icon" :disabled="slide===0" :aria-label="t('上一张')" @click="slide--"><ChevronLeft/></button><span>{{slide+1}} / {{memory.photos.length}}</span><button class="icon" :disabled="slide>=memory.photos.length-1" :aria-label="t('下一张')" @click="slide++"><ChevronRight/></button></div><div class="slide-thumbnails"><button v-for="(photo,index) in memory.photos" :key="photo.id" :class="{active:slide===index}" :aria-label="t('查看第 {0} 张',[index+1])" @click="slide=index"><img :src="media(photo.id)" alt=""></button></div></div>
 </div>
 <div class="memory-info"><div class="eyebrow">A STORY WORTH KEEPING</div><template v-if="!editing"><span class="detail-type" :style="{color:modes[memory.mode].color}">{{modes[memory.mode].label}}</span><h2 id="memory-title">{{memory.title}}</h2><div class="detail-meta"><span><CalendarDays :size="14"/>{{memory.date}}</span><span v-if="memory.place"><MapPin :size="14"/>{{memory.place}}</span></div><p class="detail-description">{{memory.description||t('有些瞬间，不用说话也会记得。')}}</p><div class="memory-tags"><span v-for="tag in memory.tags" :key="tag"># {{tag}}</span></div><p v-if="memory.rating" class="detail-rating">{{'★'.repeat(memory.rating)}}<span v-if="memory.price">{{t('¥ {0} / 人', [memory.price])}}</span></p><div class="detail-actions"><button class="primary" :disabled="!detailReady" @click="startEditing"><Pencil :size="15"/>{{t('编辑回忆')}}</button><button class="secondary" :disabled="!detailReady" @click="adding=true"><Plus :size="15"/>{{t('追加照片')}}</button></div><div class="detail-footnote"><Heart :size="14"/>{{t('同一段回忆里的照片，保留各自拍摄日期和位置。')}}</div></template>
 <form v-else class="memory-edit-form" @submit.prevent="save"><h2 id="memory-title">{{t('整理这段回忆')}}</h2><label>{{t('回忆标题')}}<input v-model="form.title" required maxlength="120"></label><div class="two-col"><label>{{t('类型')}}<select v-model="form.mode"><option v-for="(item,key) in modes" :key="key" :value="key">{{item.label}}</option></select></label><label>{{t('日期')}}<input v-model="form.date" type="date" required></label></div><label>{{t('地点')}}<input v-model="form.place" maxlength="200"></label><PlaceSearch :latitude="form.latitude" :longitude="form.longitude" @select="location"/><div class="two-col"><label>{{t('省份')}}<input v-model="form.province" maxlength="100"></label><label>{{t('城市')}}<input v-model="form.city" maxlength="100"></label></div><label>{{t('回忆备注')}}<textarea v-model="form.description" maxlength="5000" rows="4"></textarea></label><label>{{t('标签（逗号分隔）')}}<input v-model="tagText" :placeholder="t('海边，第一次旅行')"></label><div class="two-col"><label>{{t('评分')}}<select v-model.number="form.rating"><option :value="0">{{t('不评分')}}</option><option v-for="n in 5" :key="n" :value="n">{{'★'.repeat(n)}}</option></select></label><label>{{t('人均花费（元）')}}<input v-model.number="form.price" type="number" min="0" step="0.01"></label></div><details><summary>{{t('位置坐标')}}</summary><MemoryMap :photos="[]" pick :selected="form.latitude!==null&&form.longitude!==null?[form.latitude,form.longitude]:null" @select="[form.latitude,form.longitude]=$event"/><div class="two-col"><label>{{t('纬度')}}<input :value="form.latitude" type="number" step="any" min="-90" max="90" @input="coordinate($event,'latitude')"></label><label>{{t('经度')}}<input :value="form.longitude" type="number" step="any" min="-180" max="180" @input="coordinate($event,'longitude')"></label></div></details>
 <label>{{t('封面与照片顺序')}}</label><div class="photo-order-list"><div v-for="(photo,index) in ordered" :key="photo.id"><img :src="media(photo.id)" alt=""><button type="button" class="text-button" :class="{'is-cover':form.cover_id===photo.id}" @click="form.cover_id=photo.id"><Image :size="13"/>{{form.cover_id===photo.id?t('当前封面'):t('设为封面')}}</button><button type="button" class="icon" :disabled="index===0" :aria-label="t('照片前移')" @click="move(index,-1)"><ArrowUp :size="14"/></button><button type="button" class="icon" :disabled="index===ordered.length-1" :aria-label="t('照片后移')" @click="move(index,1)"><ArrowDown :size="14"/></button></div></div>
 <div class="detail-actions"><button class="primary" :disabled="busy"><Check :size="15"/>{{busy?t('保存中…'):t('保存回忆')}}</button><button type="button" class="secondary" :disabled="busy" @click="editing=false">{{t('取消')}}</button></div></form>
 <p v-if="detailError" class="error" role="alert">{{detailError}} <button class="text-button" @click="loadDetail">{{t('重新加载')}}</button></p><p v-if="!detailReady&&!detailError" class="muted" role="status">{{t('正在读取完整回忆…')}}</p><p v-if="error" class="error" role="alert">{{error}}</p><div class="memory-delete"><button v-if="!confirmDelete" class="text-button danger" @click="confirmDelete=true"><Trash2 :size="13"/>{{t('删除整段回忆')}}</button><template v-else><p>{{t('将删除这段回忆及全部 {0} 张照片，无法撤销。', [memory.photos.length])}}</p><button class="text-button danger" :disabled="busy" @click="remove">{{t('确认删除')}}</button><button class="text-button" :disabled="busy" @click="confirmDelete=false">{{t('取消')}}</button></template></div></div>
 </section></div><UploadDialog v-if="adding" :memory-id="memory.id" @close="adding=false" @uploaded="added"/><PhotoEditor v-if="editingPhoto" :photo="editingPhoto" @close="editingPhoto=null" @changed="album.refresh()"/></template>
